text:
{
  "id": "bleed",
  "name": "流血",
  "description": "物理命中有概率造成流血：每层每秒造成该次实际伤害 25% 的物理伤害，最多 5 层。",
  "params": { "chance": 50, "ratio": 0.25, "duration": 5 },
  "rules": [
    {
      "id": "bleed_on_physical_hit",
      "event": "hit",
      "chain": { "maxDepth": 4 },
      "conditions": [ { "op": "tag", "tag": "physical" }, { "op": "chance", "value": { "param": "chance" } } ],
      "actions": [ { "op": "apply_status", "key": "bleed", "value": { "mul": [ { "event": "amount" }, { "param": "ratio" } ] }, "duration": { "param": "duration" } } ]
    },
    {
      "id": "bleed_on_physical_damage",
      "event": "physical_damage_hit",
      "chain": { "maxDepth": 4 },
      "conditions": [ { "op": "chance", "value": { "param": "chance" } } ],
      "actions": [ { "op": "apply_status", "key": "bleed", "value": { "mul": [ { "event": "amount" }, { "param": "ratio" } ] }, "duration": { "param": "duration" } } ]
    },
    {
      "id": "bleed_on_slash",
      "event": "slash_hit",
      "chain": { "maxDepth": 4 },
      "conditions": [ { "op": "chance", "value": { "param": "chance" } } ],
      "actions": [ { "op": "apply_status", "key": "bleed", "value": { "mul": [ { "event": "amount" }, { "param": "ratio" } ] }, "duration": { "param": "duration" } } ]
    }
  ]
}

{
  "id": "brittle",
  "name": "易碎",
  "description": "冰冷命中已冰缓的目标时，追加该次伤害 50% 的冰冷伤害。依赖冰缓：两个特性单独都不强，合在一起才成立。",
  "params": { "ratio": 0.5 },
  "rules": [
    {
      "id": "brittle_bonus",
      "event": "hit",
      "conditions": [ { "op": "tag", "tag": "cold" }, { "op": "status", "key": "chill" } ],
      "actions": [
        { "op": "damage_target", "element": "cold", "emitEvent": "brittle_hit", "amount": { "mul": [ { "event": "damage" }, { "param": "ratio" } ] } }
      ]
    }
  ]
}

{
  "id": "chill",
  "name": "冰缓",
  "description": "任何冰冷命中都会让目标冰缓：移动与攻击变慢。同名状态不叠层，取最强值和最长时间。",
  "params": { "slow": 30, "duration": 2.0 },
  "rules": [
    {
      "id": "chill_on_cold_hit",
      "event": "hit",
      "conditions": [ { "op": "tag", "tag": "cold" } ],
      "actions": [
        { "op": "apply_status", "key": "chill", "value": { "param": "slow" }, "duration": { "param": "duration" }, "cap": 70 }
      ]
    },
    {
      "id": "chill_on_blizzard_impact", "event": "blizzard_impact_hit", "chain": { "maxDepth": 4 },
      "conditions": [ { "op": "tag", "tag": "cold" } ],
      "actions": [
        { "op": "apply_status", "key": "chill", "value": { "param": "slow" }, "duration": { "param": "duration" }, "cap": 70 }
      ]
    }
  ]
}

{
  "id": "cold_mastery",
  "name": "冰霜精通",
  "modifiers": [
    {
      "target": "element",
      "element": "cold",
      "stat": "damage_percent",
      "op": "multiply_percent",
      "value": {
        "param": "damage_percent"
      }
    },
    {
      "target": "owner",
      "stat": "critical_chance",
      "op": "add",
      "value": {
        "param": "critical_chance"
      }
    },
    {
      "target": "cast",
      "stat": "speed_percent",
      "op": "add",
      "value": {
        "param": "cast_speed"
      }
    }
  ],
  "params": {
    "damage_percent": 60,
    "critical_chance": 10,
    "cast_speed": 40
  }
}

{
  "id": "create_earth_wave",
  "name": "裂地波",
  "description": "向瞄准方向掀起一道直线地裂，对直线范围（默认长 7 米、宽 1.2 米）内的敌人造成 damage 点物理伤害。cooldown 为冷却秒数。直线范围技能：受直线长度 / 宽度及其他范围词条影响。",
  "params": { "radius": 1.2, "damage": 22, "cooldown": 0.6 },
  "rules": [
    {
      "id": "earth_wave_on_cast", "event": "cast",
      "actions": [
        { "op": "damage_area", "element": "physical", "tags": ["physical", "melee", "line"], "radius": { "param": "radius" }, "amount": { "max": [{ "param": "damage" }, { "event": "amount" }] } }
      ]
    }
  ]
}

{
  "id": "create_flame_burst",
  "name": "烈焰爆发",
  "description": "在瞄准方向的落点引爆一团烈焰，对 radius 米（默认 2.2）内的敌人造成 damage 点火焰伤害（技能威力更高时取技能威力）。cooldown 为冷却秒数。范围技能：受范围面积、形状、重复、扩散等范围词条影响。",
  "params": { "radius": 2.2, "damage": 24, "cooldown": 0.8 },
  "rules": [
    {
      "id": "flame_burst_on_cast", "event": "cast",
      "actions": [
        { "op": "damage_area", "element": "fire", "tags": ["fire", "spell"], "radius": { "param": "radius" }, "amount": { "max": [{ "param": "damage" }, { "event": "amount" }] } }
      ]
    }
  ]
}

{
  "id": "create_ice_lance",
  "name": "创建冰锥",
  "description": "施法时朝瞄准方向发射一枚冰锥。数量、扩散、速度、穿透都读取构筑属性，因此会被其他特性放大。",
  "params": { "damage": 16 },
  "modifiers": [
    { "target": "projectile", "stat": "speed", "op": "set", "value": 24 },
    { "target": "projectile", "stat": "lifetime", "op": "set", "value": 1.1 },
    { "target": "projectile", "stat": "radius", "op": "set", "value": 0.22 },
    { "target": "projectile", "stat": "spread", "op": "set", "value": 24 }
  ],
  "rules": [
    {
      "id": "cast_ice_lance",
      "event": "cast",
      "actions": [
        { "op": "emit", "kind": "ice_lance", "element": "cold", "tags": ["cold", "spell"], "damage": { "max": [ { "param": "damage" }, { "event": "amount" } ] } }
      ]
    }
  ]
}

{
  "id": "create_lightning_nova",
  "name": "雷霆新星",
  "description": "在瞄准落点释放闪电新星，对 radius 米内的敌人造成 damage 点闪电伤害；技能威力更高时取技能威力。cooldown 为手动施放冷却秒数。接受现有范围、重复、感电和触发词条；作为挂载技能时由触发词条决定落点与节奏。",
  "params": { "radius": 2.4, "damage": 28, "cooldown": 0.8 },
  "rules": [
    {
      "id": "lightning_nova_on_cast",
      "event": "cast",
      "actions": [
        {
          "op": "damage_area",
          "element": "lightning",
          "tags": ["lightning", "spell"],
          "radius": { "param": "radius" },
          "amount": { "max": [{ "param": "damage" }, { "event": "amount" }] }
        }
      ]
    }
  ]
}

{
  "id": "death_lightning",
  "name": "死亡闪电",
  "description": "击败感电敌人后，开启跟随自身的雷暴。雷暴按间隔自动索敌，从空中落雷打击目标，并在落点造成圆形闪电范围伤害。radius 为索敌半径（米），impact_radius 为落雷伤害半径（米），duration 为雷暴持续秒数，interval 为落雷间隔，amount 为伤害。再次击败感电敌人刷新雷暴。",
  "params": { "radius": 8, "impact_radius": 1.5, "duration": 6, "interval": 0.4, "amount": 30 },
  "rules": [
    {
      "id": "death_lightning_on_shocked_kill",
      "event": "kill",
      "chain": { "maxDepth": 4 },
      "conditions": [ { "op": "status", "key": "shock" } ],
      "actions": [
        { "op": "storm", "kind": "death_lightning", "event": "death_lightning_strike", "origin": "owner", "tags": ["lightning", "spell"], "duration": { "param": "duration" }, "interval": { "param": "interval" }, "radius": { "param": "radius" }, "cap": 1 }
      ]
    },
    {
      "id": "death_lightning_strikes_target",
      "event": "death_lightning_strike",
      "actions": [
        { "op": "damage_area", "element": "lightning", "tags": ["lightning", "death_lightning"], "emitEvent": "death_lightning_hit", "radius": { "param": "impact_radius" }, "amount": { "param": "amount" } }
      ]
    }
  ]
}

{
  "id": "ember_hound_bite",
  "parent": "summon_ember_hound",
  "name": "战犬·焰咬",
  "description": "辅助赤焰战犬，使其每次攻击时触发焰咬；基础火焰伤害 +damage。damage 为基础伤害（点）。以战犬位置为中心造成火焰范围命中伤害；radius 为基础伤害半径（米）。只有贴近敌人后才发动。",
  "params": {
    "damage": 16,
    "radius": 1.6
  },
  "rules": [
    {
      "id": "ember_hound_bite_on_attack",
      "event": "ember_hound_attack",
      "actions": [
        {
          "op": "damage_area",
          "element": "fire",
          "tags": [
            "fire",
            "melee"
          ],
          "radius": {
            "param": "radius"
          },
          "amount": {
            "param": "damage"
          }
        }
      ]
    }
  ]
}

{
  "id": "fire_damage",
  "name": "火焰伤害",
  "description": "命中时追加火焰伤害，受目标火焰抗性影响。追加命中使用独立事件。",
  "params": { "amount": 10 },
  "rules": [
    {
      "id": "fire_damage_on_hit",
      "event": "hit",
      "actions": [
        { "op": "damage_target", "element": "fire", "tags": ["fire"], "emitEvent": "fire_damage_hit", "amount": { "param": "amount" } }
      ]
    }
  ]
}

{
  "id": "fire_resistance",
  "name": "火焰抗性",
  "description": "目标的防御构筑增加火焰抗性；正抗性按百分比减伤，默认上限为 75%。",
  "params": { "resistance": 25 },
  "modifiers": [
    { "target": "element", "element": "fire", "stat": "resistance", "op": "add", "value": { "param": "resistance" } }
  ]
}

{
  "id": "fire_turret_fireball",
  "parent": "summon_fire_turret",
  "name": "炮台·火球",
  "description": "辅助火球炮台，使其每次攻击时触发火球；基础火焰伤害 +damage。damage 为基础伤害（点）。向锁定敌人发射火球；speed 为基础弹速（米/秒），lifetime 为飞行时间（秒），projectile_radius 为碰撞半径（米），默认最远飞行约 12.6 米。弹道参数只作用于本次发射，多重、穿透等既有投射物词条照常生效。",
  "params": {
    "damage": 14,
    "speed": 18,
    "lifetime": 0.7,
    "projectile_radius": 0.2
  },
  "rules": [
    {
      "id": "fire_turret_fireball_on_attack",
      "event": "fire_turret_attack",
      "actions": [
        {
          "op": "emit",
          "kind": "fireball",
          "element": "fire",
          "tags": [
            "fire",
            "spell"
          ],
          "speed": {
            "param": "speed"
          },
          "lifetime": {
            "param": "lifetime"
          },
          "radius": {
            "param": "projectile_radius"
          },
          "damage": {
            "param": "damage"
          }
        }
      ]
    }
  ]
}

{
  "id": "freeze",
  "name": "冻结",
  "description": "冰冷命中已被冰缓到一定强度的目标时，有概率将其冻结：完全无法移动和行动。",
  "params": { "chance": 30, "chill": 20, "duration": 1.2 },
  "rules": [
    {
      "id": "freeze_chilled_on_cold_hit",
      "event": "hit",
      "chain": { "maxDepth": 4 },
      "conditions": [
        { "op": "tag", "tag": "cold" },
        { "op": "status", "key": "chill", "compare": "gte", "value": { "param": "chill" } },
        { "op": "chance", "value": { "param": "chance" } }
      ],
      "actions": [
        { "op": "apply_status", "key": "freeze", "value": 1, "duration": { "param": "duration" } }
      ]
    }
  ]
}

{
  "id": "frost_damage",
  "name": "冰霜伤害",
  "description": "命中时追加冰霜伤害，受目标冰霜抗性影响。追加命中使用独立事件。",
  "params": { "amount": 10 },
  "rules": [
    {
      "id": "frost_damage_on_hit",
      "event": "hit",
      "actions": [
        { "op": "damage_target", "element": "frost", "tags": ["frost", "cold"], "emitEvent": "frost_damage_hit", "amount": { "param": "amount" } }
      ]
    }
  ]
}

{
  "id": "frost_resistance",
  "name": "冰霜抗性",
  "description": "目标的防御构筑增加冰霜抗性；正抗性按百分比减伤，默认上限为 75%。",
  "params": { "resistance": 25 },
  "modifiers": [
    { "target": "element", "element": "frost", "stat": "resistance", "op": "add", "value": { "param": "resistance" } }
  ]
}

{
  "id": "hobble",
  "name": "缓速",
  "description": "任何命中都使目标缓速：移动速度降低 20%，可叠 3 层（上限 60%）。",
  "params": { "amount": 20, "duration": 2 },
  "rules": [
    {
      "id": "slow_on_hit",
      "event": "hit",
      "actions": [ { "op": "apply_status", "key": "slow", "value": { "param": "amount" }, "duration": { "param": "duration" } } ]
    }
  ]
}

{
  "id": "ignite",
  "name": "点燃",
  "description": "火焰命中点燃目标：每秒造成该次实际伤害 40% 的火焰伤害，持续 4 秒。同名取最强。",
  "params": { "ratio": 0.4, "duration": 4 },
  "rules": [
    {
      "id": "ignite_on_fire_hit",
      "event": "hit",
      "chain": { "maxDepth": 4 },
      "conditions": [ { "op": "tag", "tag": "fire" } ],
      "actions": [ { "op": "apply_status", "key": "ignite", "value": { "mul": [ { "event": "amount" }, { "param": "ratio" } ] }, "duration": { "param": "duration" } } ]
    },
    {
      "id": "ignite_on_fire_damage",
      "event": "fire_damage_hit",
      "chain": { "maxDepth": 4 },
      "actions": [ { "op": "apply_status", "key": "ignite", "value": { "mul": [ { "event": "amount" }, { "param": "ratio" } ] }, "duration": { "param": "duration" } } ]
    }
  ]
}

{
  "id": "iron_guard_slash",
  "parent": "summon_iron_guard",
  "name": "铁卫·斩击",
  "description": "辅助铁刃守卫，使其每次攻击时触发斩击；基础物理伤害 +damage。damage 为基础伤害（点）。对贴近并锁定的敌人造成物理命中伤害。",
  "params": {
    "damage": 18
  },
  "rules": [
    {
      "id": "iron_guard_slash_on_attack",
      "event": "iron_guard_attack",
      "actions": [
        {
          "op": "damage_target",
          "element": "physical",
          "tags": [
            "physical",
            "melee"
          ],
          "amount": {
            "param": "damage"
          }
        }
      ]
    }
  ]
}

{
  "id": "lightning_damage",
  "name": "闪电伤害",
  "description": "命中时追加闪电伤害，受目标闪电抗性影响。追加命中使用独立事件。",
  "params": { "amount": 10 },
  "rules": [
    {
      "id": "lightning_damage_on_hit",
      "event": "hit",
      "actions": [
        { "op": "damage_target", "element": "lightning", "tags": ["lightning"], "emitEvent": "lightning_damage_hit", "amount": { "param": "amount" } }
      ]
    }
  ]
}

{
  "id": "lightning_resistance",
  "name": "闪电抗性",
  "description": "目标的防御构筑增加闪电抗性；正抗性按百分比减伤，默认上限为 75%。",
  "params": { "resistance": 25 },
  "modifiers": [
    { "target": "element", "element": "lightning", "stat": "resistance", "op": "add", "value": { "param": "resistance" } }
  ]
}

{
  "id": "monster_bolt",
  "name": "怪物飞弹",
  "description": "怪物远程攻击：朝目标发射一枚投射物，伤害取怪物攻击威力。",
  "rules": [
    {
      "id": "bolt",
      "event": "cast",
      "actions": [
        {
          "op": "emit",
          "kind": "monster_bolt",
          "element": "void",
          "inheritance": "explicit",
          "tags": [
            "spell"
          ],
          "count": {
            "param": "count"
          },
          "speed": {
            "param": "speed"
          },
          "lifetime": {
            "param": "lifetime"
          },
          "radius": {
            "param": "radius"
          },
          "damage": {
            "event": "amount"
          }
        }
      ]
    }
  ],
  "params": {
    "count": 1,
    "speed": 13,
    "lifetime": 2.2,
    "radius": 0.3
  }
}

{
  "id": "monster_claw",
  "name": "爪击",
  "params": { "damage": 7, "radius": 1.5 },
  "rules": [
    {
      "id": "claw",
      "event": "cast",
      "actions": [
        { "op": "damage_area", "element": "physical", "tags": ["physical", "melee"], "emitEvent": "claw_hit", "radius": { "param": "radius" }, "amount": { "param": "damage" } }
      ]
    }
  ]
}

{
  "id": "monster_nova",
  "name": "首领新星",
  "description": "首领技能：向四周环形发射 12 枚投射物，每枚伤害为攻击威力的 60%。",
  "rules": [
    {
      "id": "nova",
      "event": "cast",
      "actions": [
        {
          "op": "emit",
          "kind": "monster_bolt",
          "element": "void",
          "layout": "radial",
          "origin": "owner",
          "inheritance": "explicit",
          "tags": [
            "spell"
          ],
          "count": {
            "param": "count"
          },
          "speed": {
            "param": "speed"
          },
          "lifetime": {
            "param": "lifetime"
          },
          "radius": {
            "param": "radius"
          },
          "damage": {
            "mul": [
              {
                "event": "amount"
              },
              {
                "param": "damage_ratio"
              }
            ]
          }
        }
      ]
    }
  ],
  "params": {
    "count": 12,
    "speed": 10,
    "lifetime": 2.6,
    "radius": 0.35,
    "damage_ratio": 0.6
  }
}

{
  "id": "monster_strike",
  "name": "怪物近战",
  "description": "怪物近战攻击：在攻击点结算范围伤害，伤害取怪物攻击威力。",
  "params": { "radius": 1.4 },
  "rules": [
    {
      "id": "strike",
      "event": "cast",
      "actions": [
        { "op": "damage_area", "element": "physical", "tags": ["melee", "physical"], "emitEvent": "strike_hit", "radius": { "param": "radius" }, "amount": { "event": "amount" } }
      ]
    }
  ]
}

{
  "id": "monster_tower_level",
  "name": "塔层级",
  "description": "怪物生成时按所在塔层修饰生命上限与造成的命中伤害。level 为塔层（从第 1 层起）；life_growth 为每升一层的生命倍率，默认 2；damage_growth 为每升一层的伤害倍率，默认 1.2。第 1 层不加成，第 N 层分别乘 life_growth^(N-1) 与 damage_growth^(N-1)。同一怪物仅保留一份，更新层级时按原始属性重算，不重复累乘；生命上限及伤害倍率沿用引擎 10 亿硬上限。",
  "params": {
    "level": 1,
    "life_growth": 2,
    "damage_growth": 1.2
  },
  "modifiers": [
    {
      "target": "owner",
      "stat": "max_life",
      "op": "multiply",
      "value": { "pow": [{ "param": "life_growth" }, { "max": [0, { "add": [{ "param": "level" }, -1] }] }] }
    },
    {
      "target": "owner",
      "stat": "damage_multiplier",
      "op": "multiply",
      "value": { "pow": [{ "param": "damage_growth" }, { "max": [0, { "add": [{ "param": "level" }, -1] }] }] }
    }
  ]
}

{
  "id": "multiple_projectiles",
  "name": "多重投射",
  "description": "所有继承构筑属性的投射物每次发射增加 4 枚，扩散设为 50 度，投射物伤害乘以 0.75；包括召唤物发射的投射物。",
  "modifiers": [
    {
      "target": "projectile",
      "stat": "count",
      "op": "add",
      "value": {
        "param": "count"
      }
    },
    {
      "target": "projectile",
      "stat": "spread",
      "op": "set",
      "value": {
        "param": "spread"
      }
    },
    {
      "target": "projectile",
      "stat": "damage",
      "op": "multiply",
      "value": {
        "param": "damage_multiplier"
      }
    }
  ],
  "params": {
    "count": 4,
    "spread": 50,
    "damage_multiplier": 0.75
  }
}

{
  "id": "physical_damage",
  "name": "物理伤害",
  "description": "命中时追加物理伤害。追加命中使用独立事件，避免再次触发自身。",
  "params": { "amount": 10 },
  "rules": [
    {
      "id": "physical_damage_on_hit",
      "event": "hit",
      "actions": [
        { "op": "damage_target", "element": "physical", "tags": ["physical"], "emitEvent": "physical_damage_hit", "amount": { "param": "amount" } }
      ]
    }
  ]
}

{
  "id": "pierce",
  "name": "穿透",
  "description": "所有继承构筑属性的投射物增加 2 次穿透，包括召唤物发射的投射物。",
  "modifiers": [
    {
      "target": "projectile",
      "stat": "pierce",
      "op": "add",
      "value": {
        "param": "count"
      }
    }
  ],
  "params": {
    "count": 2
  }
}

{
  "id": "player_slash",
  "name": "斩击",
  "description": "近战挥砍：在角色前方结算一次范围伤害。伤害取施法威力（武器/招式伤害）。",
  "params": { "radius": 2.2 },
  "rules": [
    {
      "id": "slash",
      "event": "cast",
      "actions": [
        { "op": "damage_area", "element": "physical", "tags": ["melee", "physical"], "emitEvent": "slash_hit", "radius": { "param": "radius" }, "amount": { "event": "amount" } }
      ]
    }
  ]
}

{
  "id": "poison_damage",
  "name": "中毒伤害",
  "description": "命中时追加中毒类型的直接伤害，受目标中毒抗性影响。追加命中使用独立事件。",
  "params": { "amount": 10 },
  "rules": [
    {
      "id": "poison_damage_on_hit",
      "event": "hit",
      "actions": [
        { "op": "damage_target", "element": "poison", "tags": ["poison"], "emitEvent": "poison_damage_hit", "amount": { "param": "amount" } }
      ]
    }
  ]
}

{
  "id": "poison_flask_burst",
  "name": "毒瓶破裂",
  "parent": "throw_poison_flask",
  "description": "辅助毒瓶，使其碰撞或达到飞行距离后触发破裂；基础毒素伤害 +damage，基础爆炸半径 +radius 米。damage 为基础毒素伤害（点），radius 为落点周围的爆炸半径（米）。碰撞包括目标和地形；只响应毒瓶载体，容量回收不爆炸，范围命中使用独立事件。",
  "params": { "radius": 2.4, "damage": 18 },
  "rules": [
    {
      "id": "burst_on_impact", "event": "projectile_end", "chain": { "maxDepth": 4 },
      "conditions": [ { "op": "tag", "tag": "poison_flask" }, { "op": "tag", "tag": "end_impact" } ],
      "actions": [ { "op": "damage_area", "element": "poison", "tags": ["poison", "spell", "poison_flask"], "emitEvent": "poison_flask_hit", "radius": { "param": "radius" }, "amount": { "param": "damage" } } ]
    },
    {
      "id": "burst_on_landing", "event": "projectile_end", "chain": { "maxDepth": 4 },
      "conditions": [ { "op": "tag", "tag": "poison_flask" }, { "op": "tag", "tag": "end_expired" } ],
      "actions": [ { "op": "damage_area", "element": "poison", "tags": ["poison", "spell", "poison_flask"], "emitEvent": "poison_flask_hit", "radius": { "param": "radius" }, "amount": { "param": "damage" } } ]
    }
  ]
}

{
  "id": "poison_flask_poison",
  "name": "毒瓶施毒",
  "parent": "throw_poison_flask",
  "description": "辅助毒瓶，使其范围命中时触发中毒；基础中毒持续时间 +duration 秒。duration 为基础中毒持续时间（秒）。中毒沿用现有逐层结算：基础每秒伤害为本次实际命中伤害的 20%，并受现有中毒词条影响。",
  "params": { "duration": 2 },
  "rules": [
    {
      "id": "poison_on_flask_burst", "event": "poison_flask_hit", "chain": { "maxDepth": 4 },
      "actions": [ { "op": "apply_status", "key": "poison", "value": { "event": "amount" }, "duration": { "param": "duration" } } ]
    }
  ]
}

{
  "id": "poison_resistance",
  "name": "中毒抗性",
  "description": "目标的防御构筑增加中毒抗性；正抗性按百分比减伤，默认上限为 75%。",
  "params": { "resistance": 25 },
  "modifiers": [
    { "target": "element", "element": "poison", "stat": "resistance", "op": "add", "value": { "param": "resistance" } }
  ]
}

{
  "id": "projectile_reflect",
  "name": "投射物反射",
  "description": "投射物命中敌人后沿原方向反向弹回（不追踪施法者），途中可以命中其他敌人（不会重复命中同一敌人，与 UE 一致）。count = 可反射次数。",
  "params": { "count": 1 },
  "modifiers": [ { "target": "projectile", "stat": "reflection_count", "op": "add", "value": { "param": "count" } } ],
  "rules": [
    {
      "id": "reflect_on_hit",
      "event": "hit",
      "chain": { "maxDepth": 8 },
      "conditions": [ { "op": "tag", "tag": "projectile" } ],
      "actions": [ { "op": "redirect", "mode": "reflect" } ]
    }
  ]
}

{
  "id": "projectile_return",
  "name": "投射物回归",
  "description": "投射物命中敌人后掉头飞向施法者当前位置，回程可以命中路上的其他敌人（同一枚投射物不会重复命中同一敌人，与 UE 一致）。count = 可回归次数。",
  "params": { "count": 1 },
  "modifiers": [ { "target": "projectile", "stat": "return_count", "op": "add", "value": { "param": "count" } } ],
  "rules": [
    {
      "id": "return_on_hit",
      "event": "hit",
      "chain": { "maxDepth": 8 },
      "conditions": [ { "op": "tag", "tag": "projectile" } ],
      "actions": [ { "op": "redirect", "mode": "return" } ]
    }
  ]
}

{
  "id": "ricochet",
  "name": "弹射",
  "description": "所有继承构筑属性的投射物增加 2 次弹射，命中后寻找附近敌人继续飞行；包括召唤物发射的投射物。",
  "modifiers": [
    {
      "target": "projectile",
      "stat": "ricochet_count",
      "op": "add",
      "value": {
        "param": "count"
      }
    }
  ],
  "rules": [
    {
      "id": "ricochet_on_hit",
      "event": "hit",
      "chain": {
        "maxDepth": 8
      },
      "conditions": [
        {
          "op": "tag",
          "tag": "projectile"
        }
      ],
      "actions": [
        {
          "op": "redirect",
          "mode": "ricochet"
        }
      ]
    }
  ],
  "params": {
    "count": 2
  }
}

{
  "id": "sentinel_fire_nova",
  "parent": "summon_sentinel",
  "name": "哨卫·火焰新星",
  "description": "辅助哨卫，使其每次攻击时触发火焰新星；基础火焰伤害 +amount，基础半径 +radius 米。amount 为基础火焰伤害（点），radius 为以哨卫自身为中心的半径（米），对范围内所有敌人生效。只在锁定范围内有敌人时爆发；半径受范围加成影响，算作命中。",
  "params": { "amount": 10, "radius": 2.5 },
  "rules": [
    {
      "id": "sentinel_fire_nova_burst", "event": "sentinel_attack",
      "actions": [
        { "op": "damage_area", "element": "fire", "tags": ["fire", "spell"], "radius": { "param": "radius" }, "amount": { "param": "amount" } }
      ]
    }
  ]
}

{
  "id": "sentinel_ice_lance",
  "parent": "summon_sentinel",
  "name": "哨卫·冰锥",
  "description": "辅助哨卫，使其每次攻击时触发冰锥；基础冰霜伤害 +damage，基础弹速 +speed 米/秒，基础飞行时间 +lifetime 秒，基础碰撞半径 +projectile_radius 米。冰锥发射向锁定的敌人，damage 为基础冰霜伤害（点），技能威力更高时取技能威力。speed 为弹速（米/秒），lifetime 为飞行秒数，projectile_radius 为碰撞半径（米）；默认飞行约 10.8 米。多重、穿透、弹射等投射物特性和冰缓照常生效。",
  "params": { "damage": 16, "speed": 24, "lifetime": 0.45, "projectile_radius": 0.22 },
  "rules": [
    {
      "id": "sentinel_fires_ice_lance", "event": "sentinel_attack",
      "actions": [
        { "op": "emit", "kind": "ice_lance", "element": "frost", "tags": ["frost", "cold", "spell"], "speed": { "param": "speed" }, "lifetime": { "param": "lifetime" }, "radius": { "param": "projectile_radius" }, "damage": { "max": [{ "param": "damage" }, { "event": "amount" }] } }
      ]
    }
  ]
}

{
  "id": "sentinel_lightning",
  "parent": "summon_sentinel",
  "name": "哨卫·落雷",
  "description": "辅助哨卫，使其每次攻击时触发落雷；基础闪电伤害 +amount。amount 为基础闪电伤害（点），直接对锁定的敌人生效，必中且不产生投射物。算作命中，会触发感电等命中时特性。",
  "params": { "amount": 12 },
  "rules": [
    {
      "id": "sentinel_calls_lightning", "event": "sentinel_attack",
      "actions": [
        { "op": "damage_target", "element": "lightning", "tags": ["lightning", "spell"], "amount": { "param": "amount" } }
      ]
    }
  ]
}

{
  "id": "shatter",
  "name": "碎裂",
  "description": "击杀冰缓目标时炸开，对周围造成冰冷范围伤害。碎裂伤害本身是冰冷命中，会继续冰缓、继续触发碎裂（最多 3 层）。",
  "params": { "radius": 2.6, "amount": 22 },
  "rules": [
    {
      "id": "shatter_on_chilled_kill",
      "event": "kill",
      "chain": { "channel": "shatter", "maxDepth": 3 },
      "conditions": [ { "op": "status", "key": "chill" } ],
      "actions": [
        { "op": "damage_area", "element": "cold", "tags": ["cold", "shatter"], "radius": { "param": "radius" }, "amount": { "param": "amount" } }
      ]
    }
  ]
}

