    {
      "id": "shock_on_lightning_damage",
      "event": "lightning_damage_hit",
      "chain": { "maxDepth": 4 },
      "actions": [ { "op": "apply_status", "key": "shock", "value": { "param": "amount" }, "duration": { "param": "duration" } } ]
    },
    {
      "id": "shock_on_death_lightning_hit",
      "event": "death_lightning_hit",
      "chain": { "maxDepth": 4 },
      "actions": [ { "op": "apply_status", "key": "shock", "value": { "param": "amount" }, "duration": { "param": "duration" } } ]
    }
